def _post_trust_credentials_verify_batch(self, tenant: str) -> None:
    # 批量外部凭证验真：与单项相同的公开错误协议，任何失败都
    # 返回 HTTP 200。请求体须恰为 {"credentials": [项...]}，数组
    # 非空且不超过 100 项；请求体非法（含非法 JSON、空数组、超过
    # 上限）时返回 {"results": [], "reason": "请求..."}。请求级
    # 合法时返回 {"results": [...]}，长度与顺序与输入一致，逐项
    # 复用单项验真规则，失败不短路。只读，不写任何状态、不记审计。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    try:
        ok, reason, results = store.verify_trust_credentials_batch(
            tenant, data
        )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 验签过程发生内部错误"}
        )
        return
    if not ok:
        self._send_json(
            200, {"results": [], "reason": reason or "请求不合法"}
        )
        return
    self._send_json(200, {"results": results})

def _post_trust_credentials_verify_batch_with_status(
    self, tenant: str
) -> None:
    # 批量外部凭证验真并合并本租户同步状态：与 verify-batch 相同的
    # 公开错误协议，任何失败都返回 HTTP 200。请求体须恰为
    # {"credentials": [项...]}，数组非空且不超过 100 项；请求体非法
    # （含非法 JSON、空数组、超过上限）时返回
    # {"results": [], "reason": "请求..."}。请求级合法时逐项复用
    # verify-with-status 规则（验真 + 只读合并同步状态），按输入
    # 顺序返回 {"results": [...]}，失败不短路。只读，不写凭证、
    # 状态、同步记录、历史或审计。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    try:
        ok, reason, results = (
            store.verify_trust_credentials_batch_with_status(
                tenant, data
            )
        )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 验签过程发生内部错误"}
        )
        return
    if not ok:
        self._send_json(
            200, {"results": [], "reason": reason or "请求不合法"}
        )
        return
    self._send_json(200, {"results": results})

def verify_trust_credential(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """验证未在本租户签发或存储的外部凭证，返回 (是否有效, 失败原因)。

    校验顺序：请求结构 -> 凭证字段 -> 锚点 -> 签名格式 -> 密码学验签。
    - 请求体须恰含 body（对象）与 signature（非空字符串），其余字段
      （含缺失、多余字段、非对象）均按请求错误；
    - body 须含 credential_id/issuer_did/subject_did/claims/issued_at，
      依次为非空字符串、非空字符串、非空字符串、对象、非空字符串；
      issuer_key_version 可省略（按版本 1 查锚点且不得注入签名正文），
      提供时须为非布尔正整数；其他扩展字段允许且全部参与签名；
    - 锚点按本租户 (issuer_did, 版本) 查找，仅 active 的 P-256 公钥
      可用，缺失或 revoked 失败；
    - 签名为 ES256/SHA-256，64 字节裸 R||S 的无填充 base64url，覆盖
      完整 body（递归排序紧凑 JSON）；
    - 原验真成功后按当前租户查 issuer_did 外部停用通告，命中返回
      “外部签发DID已停用：<reason>”，仅他租户有通告不影响结论。
    只读：不登记 DID/凭证，不写凭证、状态或审计，绝不向上抛异常。
    """
    # 1. 请求结构
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象"
    if set(data) != {"body", "signature"}:
        missing = [f for f in ("body", "signature") if f not in data]
        if missing:
            return False, f"请求缺少字段: {', '.join(missing)}"
        extra = sorted(set(data) - {"body", "signature"})
        return False, f"请求含多余字段: {', '.join(extra)}"
    body = data["body"]
    signature = data["signature"]
    if not isinstance(body, dict):
        return False, "请求不合法: 字段 body 必须为 JSON 对象"
    if not isinstance(signature, str) or not signature:
        return False, "请求不合法: 字段 signature 必须为非空字符串"

    # 2. 凭证字段
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return False, f"凭证缺少字段: {field}"
        value = body[field]
        if not isinstance(value, str) or not value:
            return False, f"凭证字段 {field} 必须为非空字符串"
    if "claims" not in body:
        return False, "凭证缺少字段: claims"
    if not isinstance(body["claims"], dict):
        return False, "凭证字段 claims 必须为 JSON 对象"
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return False, "凭证字段 issuer_key_version 必须为正整数"
        key_version = version_obj
    issuer_did = body["issuer_did"]

    # 3. 锚点：本租户 (issuer_did, 版本)，仅 active 的 P-256 公钥
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(key_version))
            if anchors is not None else None
        )
        public_pem = row.get("public_key", "") if row is not None else ""
        status = row.get("status", "active") if row is not None else None
        uses = row.get("uses") if row is not None else None
    if row is None:
        return False, (
            f"锚点不存在: {issuer_did}#{key_version}"
        )
    if status == "revoked":
        return False, f"锚点已吊销: {issuer_did}#{key_version}"
    # 用途白名单：active 锚点无 vc 用途时按锚点不可用处理
    if uses is not None and "vc" not in uses:
        return False, (
            f"锚点不存在: {issuer_did}#{key_version}"
        )
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            f"锚点公钥不可用: {issuer_did}#{key_version} 不是合法 P-256 公钥"
        )

    # 4/5. 签名格式与密码学验签：签名覆盖完整 body 的规范化 JSON。
    # 省略 issuer_key_version 时不得向签名正文注入该字段。
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，凭证正文或签名可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 6. 有效期：仅在请求 body 提供 expires_at 时检查（缺失保持兼容，
    # 无期限）。须为 UTC 秒精度 Z 格式；当前时间 >= expires_at 判
    # 到期。只读，不写任何状态、不记审计。
    if "expires_at" in body:
        expires_value = body["expires_at"]
        if (
            not isinstance(expires_value, str)
            or not _UTC_Z_SHAPE_RE.match(expires_value)
        ):
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        try:
            expires_dt = _parse_utc_z(expires_value)
        except ValueError:
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        if datetime.now(timezone.utc) >= expires_dt:
            return False, CREDENTIAL_EXPIRED_REASON

    # 7. 原验真成功后、合并凭证状态前查本租户 issuer_did 外部停用
    #    通告：命中返回“外部签发DID已停用：<reason>”；无通告或仅他
    #    租户有通告维持原结论。只读，不写状态、不记审计。
    deactivation_reason = self._external_did_deactivation_reason(
        tenant_id, issuer_did, EXTERNAL_ISSUER_DID_DEACTIVATED_REASON_PREFIX
    )
    if deactivation_reason is not None:
        return False, deactivation_reason
    return True, ""

def verify_trust_credential_synced(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    body: Any,
    signature: Any,
) -> Tuple[bool, str]:
    """以同步锚点验真外部凭证，返回 (是否有效, 失败原因)。

    请求结构（恰含 signer_did/at/body/signature 及类型）由服务层
    校验（400）。本方法假定四键类型已合法：
    - 该签名方在本租户无同步检查点（含跨租户）抛 NotFoundError；
      at 超过检查点抛 ConflictError；
    - 凭证字段规则沿用 :meth:`verify_trust_credential`：body 须含
      credential_id/issuer_did/subject_did/claims/issued_at，
      issuer_key_version 省略按版本 1 且不注入签名正文，提供时须
      为非布尔正整数；
    - 锚点取该来源 cursor<=at 的已同步事件，以 (issuer_did, 版本)
      最后事件为准；缺失、非 active 或 uses 无 vc 均返回
      (False, "同步锚点不可用")；
    - 签名须为 ES256、64 字节裸 R||S 无填充 base64url，覆盖完整
      body 的规范化 JSON；格式错/验签错/到期依次返回
      “签名格式错误”/“签名校验失败”/“凭证已过期”；
    - expires_at 规则与 :meth:`verify_trust_credential` 一致。

    纯只读：不改同步页、检查点、锚点、凭证、状态或审计，结论随
    状态文件跨重启稳定。
    """
    with self._lock:
        checkpoints = self._anchor_changes_sync_checkpoints.get(
            tenant_id
        )
        cp = (
            checkpoints.get(signer_did)
            if checkpoints is not None else None
        )
        if cp is None:
            raise NotFoundError("该签名方尚未同步锚点变更")
        checkpoint = int(cp["next_after"])
        if at > checkpoint:
            raise ConflictError("查询时间点超过同步检查点")
        bucket = self._bucket_locked(tenant_id)
        pages: List[Dict[str, Any]] = []
        if bucket is not None:
            pages = bucket.get("synced_anchor_change_pages", {}).get(
                signer_did, []
            )
        latest: Dict[Tuple[str, int], Dict[str, Any]] = {}
        for page in pages:
            for event in page["events"]:
                cursor = int(event["cursor"])
                if cursor > at:
                    continue
                key = (event["did"], int(event["key_version"]))
                existing = latest.get(key)
                if existing is None or cursor > int(
                    existing["cursor"]
                ):
                    latest[key] = event

    # 凭证字段（沿用 /v1/trust/credentials/verify 的分类原因）
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return False, f"凭证缺少字段: {field}"
        value = body[field]
        if not isinstance(value, str) or not value:
            return False, f"凭证字段 {field} 必须为非空字符串"
    if "claims" not in body:
        return False, "凭证缺少字段: claims"
    if not isinstance(body["claims"], dict):
        return False, "凭证字段 claims 必须为 JSON 对象"
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return False, "凭证字段 issuer_key_version 必须为正整数"
        key_version = version_obj
    issuer_did = body["issuer_did"]

    # 同步锚点：(issuer_did, 版本) 最后事件，须 active 且含 vc 用途
    anchor = latest.get((issuer_did, key_version))
    if (
        anchor is None
        or anchor["status"] != "active"
        or "vc" not in anchor["uses"]
    ):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON
    public_pem = anchor["public_key"]
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON

    # 签名格式（严格：64 字节裸 R||S 无填充 base64url）与密码学
    # 验签：覆盖完整 body 的规范化 JSON，省略 issuer_key_version
    # 时不注入正文。
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    except crypto.InvalidSignature:
        return False, IMPORTED_SIGNATURE_INVALID_REASON
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, IMPORTED_SIGNATURE_INVALID_REASON

    # 有效期：仅在 body 提供 expires_at 时检查，规则同既有验真。
    if "expires_at" in body:
        expires_value = body["expires_at"]
        if (
            not isinstance(expires_value, str)
            or not _UTC_Z_SHAPE_RE.match(expires_value)
        ):
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        try:
            expires_dt = _parse_utc_z(expires_value)
        except ValueError:
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        if datetime.now(timezone.utc) >= expires_dt:
            return False, CREDENTIAL_EXPIRED_REASON
    return True, ""

def verify_trust_credential_with_status(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """外部凭证验真并合并本地同步状态判定（只读）。

    先按 :meth:`verify_trust_credential` 的全部规则完成外部凭证验真
    （请求结构 → 凭证字段 → 锚点 → 签名格式 → 密码学验签 →
    expires_at → 签发 DID 停用通告），失败原样返回 ``(False, 原因)``，
    保持既有优先级与中文原因分类；签名覆盖请求提交的完整 ``body``，
    省略 ``issuer_key_version`` 时按版本 1 且不注入正文。

    验签通过后按当前租户 ``(issuer_did, credential_id)`` 双键只读
    查询 ``credential_status_sync`` 同步记录：
      - 未同步（含属他租户）：``(False, "外部凭证状态未同步")``；
      - active：``(True, "")``；
      - revoked：``(False, "外部凭证已吊销：<保存的 reason>")``，
        保存记录无 reason 时用“未知原因”；
      - unknown：``(False, "外部凭证状态未知")``。

    纯只读：不创建凭证、不修改本地状态、不写同步记录、不记审计。
    """
    valid, reason = self.verify_trust_credential(tenant_id, data)
    if not valid:
        return False, reason

    body = data["body"]
    issuer_did = body["issuer_did"]
    credential_id = body["credential_id"]
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = None
        if bucket is not None:
            row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
    if row is None:
        return False, "外部凭证状态未同步"
    status = row.get("status")
    if status == "active":
        return True, ""
    if status == "revoked":

    length = int(self.headers.get("Content-Length") or 0)
    raw = self.rfile.read(length) if length else b""
    if not raw:
        return {}
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise ValidationError("请求体必须为 JSON 对象")
    return data

